    public QaGovernanceCoreEngine(IQaGovernanceRepository repo,IUnitOfWork uow,ISystemClock clock,IProjectRepository projects,IBenchmarkRepository benchmarks,IRepositoryOwnershipResolver repositoryOwnership,IQaFindingRepository qaFindings,IDipOperationalMetrics metrics){_repo=repo;_uow=uow;_clock=clock;_projects=projects;_benchmarks=benchmarks;_repositoryOwnership=repositoryOwnership;_qaFindings=qaFindings;_metrics=metrics;}

    public async Task ProcessCompletedRunAsync(QaRun run,IReadOnlyList<QaFinding> findings,CancellationToken ct)
    {
        var now=_clock.UtcNow;var waivers=(await _repo.ListWaiversAsync(run.ProjectId,ct)).ToList();foreach(var w in waivers)w.Expire(now);var activeWaivers=waivers.Where(x=>x.IsActive(now)).ToArray();var ownership=await _repo.ListOwnershipRulesAsync(run.ProjectId,ct);var observed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach(var finding in findings)
        {
            observed.Add(finding.Fingerprint);var state=await _repo.FindFindingStateAsync(run.ProjectId,finding.Fingerprint,ct);if(state is null){state=new QaFindingState(Guid.NewGuid(),run.ProjectId,finding.Fingerprint,finding.Id,run.SubjectKey,run.CommitSha,now);await _repo.AddFindingStateAsync(state,ct);}else state.Observe(finding.Id,run.CommitSha,now);
            var waiver=activeWaivers.FirstOrDefault(x=>MatchesWaiver(x,finding));if(waiver is not null)state.Transition(FindingLifecycleStatus.Suppressed,$"Active waiver: {waiver.Name}; expires {waiver.ExpiresAtUtc:O}",waiver.ApprovedBy??waiver.RequestedBy,now);else if(state.Status==FindingLifecycleStatus.Suppressed)state.Transition(FindingLifecycleStatus.Confirmed,"The previous waiver no longer applies.","DIP",now);
            if(waiver is null&&TryOwner(ownership,finding.FilePath,out var owner))state.Assign(owner!.Team,owner.Workstream,QaOwnershipSource.Rule,now);else if(waiver is null){var resolved=await _repositoryOwnership.ResolveAsync(run.WorkspaceRelativePath,finding.FilePath,ct);if(resolved is not null)state.Assign(resolved.Team,resolved.Workstream,QaOwnershipSource.CodeOwners,now);}
        }
        await _uow.SaveChangesAsync(ct);
        var states=await _repo.ListFindingStatesAsync(run.ProjectId,10000,ct);if(run.Status!=QaRunStatus.InfrastructureFailure)
        {
            foreach(var state in states.Where(x=>string.Equals(x.SubjectKey,run.SubjectKey,StringComparison.OrdinalIgnoreCase)&&!observed.Contains(x.Fingerprint)))
            {
                if(state.Status is FindingLifecycleStatus.New or FindingLifecycleStatus.Confirmed or FindingLifecycleStatus.Assigned or FindingLifecycleStatus.InProgress)state.Transition(FindingLifecycleStatus.Fixed,"Not observed in the latest completed QA run.","DIP",now);
                else if(state.Status==FindingLifecycleStatus.Fixed)state.Transition(FindingLifecycleStatus.Verified,"Absent from two consecutive completed QA runs.","DIP",now);
                else if(state.Status==FindingLifecycleStatus.Suppressed){var last=await _qaFindings.GetAsync(state.LastFindingId,ct);if(last is not null&&!activeWaivers.Any(x=>MatchesWaiver(x,last)))state.Transition(FindingLifecycleStatus.Fixed,"The waiver no longer applies and the finding was not observed in the latest completed QA run.","DIP",now);}
            }
        }

        var suiteKey=$"suite:{run.SubjectKey}";var suite=await _repo.FindReliabilityAsync(run.ProjectId,suiteKey,ct);if(suite is null){suite=new QaTestReliability(Guid.NewGuid(),run.ProjectId,suiteKey,now);await _repo.AddReliabilityAsync(suite,ct);}var infra=run.Status==QaRunStatus.InfrastructureFailure;var suitePassed=!infra&&!findings.Any(IsProductFailure);suite.Observe(suitePassed,infra,run.CommitSha,now);
        foreach(var f in findings.Where(x=>x.Category.Contains("test",StringComparison.OrdinalIgnoreCase)))
        {
            var key=$"test:{f.Title}";var rel=await _repo.FindReliabilityAsync(run.ProjectId,key,ct);if(rel is null){rel=new QaTestReliability(Guid.NewGuid(),run.ProjectId,key,now);await _repo.AddReliabilityAsync(rel,ct);}
            if(f.TotalAttempts>=3&&(f.ReproductionStatus is ReproductionStatus.Reproduced or ReproductionStatus.NotReproduced))
            {for(var i=0;i<f.ReproducedAttempts;i++)rel.Observe(false,false,run.CommitSha,now);for(var i=f.ReproducedAttempts;i<f.TotalAttempts;i++)rel.Observe(true,false,run.CommitSha,now);}
            else rel.Observe(false,false,run.CommitSha,now);
        }
        await _uow.SaveChangesAsync(ct);

        if(!string.IsNullOrWhiteSpace(run.CommitSha))await ObserveBaselinesAsync(run,findings,now,ct);
        var policy=await _repo.GetActivePolicyAsync(run.ProjectId,ct);var rules=ReadRules(policy);var currentStates=await _repo.ListFindingStatesAsync(run.ProjectId,10000,ct);var reliability=await _repo.ListReliabilityAsync(run.ProjectId,5000,ct);var previousHealth=await _repo.ListSystemHealthAsync(run.ProjectId,20,ct);var infrastructureFailures=previousHealth.Count(x=>x.Status==QaSystemHealthStatus.Unavailable)+(run.Status==QaRunStatus.InfrastructureFailure?1:0);var toolMs=ToolDuration(run.SummaryJson);var cpuMs=CpuDuration(run.SummaryJson);var wall=run.StartedAtUtc.HasValue&&run.FinishedAtUtc.HasValue?Math.Max(0L,(long)(run.FinishedAtUtc.Value-run.StartedAtUtc.Value).TotalMilliseconds):toolMs;var artifactBytes=DirectorySize(run.ArtifactRoot);var evaluation=EvaluatePolicy(run,findings,currentStates,reliability,activeWaivers,rules,policy,infrastructureFailures,wall,cpuMs,artifactBytes,now);await _repo.AddPolicyEvaluationAsync(evaluation,ct);
        await _repo.AddProvenanceAsync(BuildProvenance(run,findings,policy?.Version??"default-v1",now),ct);
        var health=AssessSelfHealth(run);await _repo.AddSystemHealthAsync(new QaSystemHealthSnapshot(Guid.NewGuid(),run.ProjectId,run.Id,"qa-orchestrator",health,HealthDetail(run,health),now),ct);foreach(var toolHealth in BuildToolHealthSnapshots(run,now))await _repo.AddSystemHealthAsync(toolHealth,ct);
        var flaky=reliability.Count(x=>x.Classification==TestReliabilityClassification.Flaky);var open=currentStates.Count(x=>!IsClosed(x.Status));var debt=Math.Clamp(findings.Count(x=>x.Severity==Severity.Critical)*20m+findings.Count(x=>x.Severity==Severity.Warning)*5m+flaky*10m+activeWaivers.Length*2m,0m,1000m);await _repo.AddTrendAsync(new QaQualityTrendSnapshot(Guid.NewGuid(),run.ProjectId,run.Id,open,findings.Count(x=>x.Severity==Severity.Critical),findings.Count(x=>x.Severity==Severity.Warning),flaky,activeWaivers.Length,debt,now),ct);
        var cpuSeconds=decimal.Round(cpuMs/1000m,3);var overBudget=(rules.MaxRunDurationMs>0&&wall>rules.MaxRunDurationMs)||(rules.MaxCpuSeconds>0&&cpuSeconds>rules.MaxCpuSeconds)||(rules.MaxArtifactBytes>0&&artifactBytes>rules.MaxArtifactBytes);var budget=overBudget?"OverBudget":"WithinBudget";await _repo.AddCostAsync(new QaRunCostRecord(Guid.NewGuid(),run.ProjectId,run.Id,wall,toolMs,artifactBytes,cpuSeconds,budget,now),ct);
        await _uow.SaveChangesAsync(ct);
        _metrics.GovernanceRunCompleted(run.Status.ToString(),evaluation.Verdict.ToString(),open,flaky,activeWaivers.Length,health.ToString());
    }

    public async Task<QaGovernanceOverviewDto> GetOverviewAsync(Guid projectId,CancellationToken ct)
    {var states=await _repo.ListFindingStatesAsync(projectId,10000,ct);var waivers=(await _repo.ListWaiversAsync(projectId,ct)).Count(x=>x.IsActive(_clock.UtcNow));var rel=await _repo.ListReliabilityAsync(projectId,5000,ct);var baseLines=await _repo.ListBaselinesAsync(projectId,5000,ct);var gate=await _repo.GetLatestPolicyEvaluationAsync(projectId,ct);var health=(await _repo.ListSystemHealthAsync(projectId,1,ct)).FirstOrDefault();var trends=await _repo.ListTrendsAsync(projectId,2,ct);var trend=trends.FirstOrDefault();var previous=trends.Skip(1).FirstOrDefault();var delta=trend is null||previous is null?0m:decimal.Round(trend.TechnicalDebtScore-previous.TechnicalDebtScore,2);var direction=trend is null||previous is null?"Unknown":delta<-0.01m?"Improving":delta>0.01m?"Worsening":"Stable";var active=await _repo.GetActivePolicyAsync(projectId,ct);var fresh=await GetFreshnessAsync(projectId,ReadRules(active).MaxEvidenceAgeDays,ct);return new(projectId,gate?.Verdict.ToString()??QaGateVerdict.Unavailable.ToString(),gate?.Summary??"No QA policy evaluation exists yet.",states.Count(x=>!IsClosed(x.Status)),waivers,rel.Count(x=>x.Classification==TestReliabilityClassification.Flaky),baseLines.Count(x=>x.Status==QaRegressionStatus.Regressed),health?.Status.ToString()??QaSystemHealthStatus.Unavailable.ToString(),trend?.TechnicalDebtScore??0m,fresh.Status,_clock.UtcNow,direction,delta,fresh.Confidence,fresh.ConfidencePercent);}
