    public async Task<IReadOnlyList<SmartTestSelectionDto>> SelectTestsAsync(SmartTestSelectionRequest r,CancellationToken ct)
    {var rules=await _repo.ListTestImpactRulesAsync(r.ProjectId,ct);return rules.Select(x=>new{Rule=x,Paths=r.ChangedPaths.Where(p=>Glob(x.PathPattern,p)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray()}).Where(x=>x.Paths.Length>0).OrderByDescending(x=>x.Rule.Priority).Take(Math.Clamp(r.MaximumTests,1,500)).Select(x=>new SmartTestSelectionDto(x.Rule.TestKey,x.Rule.CommandJson,x.Rule.Priority,x.Paths,$"Matched {x.Paths.Length} changed path(s) against {x.Rule.PathPattern}.")).ToArray();}
    public async Task<IReadOnlyList<TestRecommendationDto>> RecommendTestsAsync(Guid projectId,IReadOnlyList<string> changedPaths,CancellationToken ct)
    {var selected=await SelectTestsAsync(new(projectId,changedPaths,200),ct);var rel=await _repo.ListReliabilityAsync(projectId,500,ct);var list=selected.Select(x=>new TestRecommendationDto(x.TestKey,x.Reason,"High",x.CommandJson)).ToList();foreach(var flaky in rel.Where(x=>x.Classification==TestReliabilityClassification.Flaky).OrderByDescending(x=>x.FailureRatePercent).Take(20))if(list.All(x=>!x.TestKey.Equals(flaky.TestKey,StringComparison.OrdinalIgnoreCase)))list.Add(new(flaky.TestKey,$"Flaky history: {flaky.FailureRatePercent:0.##}% failure rate across {flaky.PassCount+flaky.FailCount} observations.","High",null));if(changedPaths.Count>0&&selected.Count==0)list.Add(new("coverage-gap","No test-impact rule covers the changed paths. Add an ownership/test-impact mapping before release.","High",null));return list;}
    public async Task<RootCauseCorrelationDto> CorrelateAsync(Guid projectId,string fingerprint,CancellationToken ct)
    {var state=await _repo.FindFindingStateAsync(projectId,fingerprint,ct)??throw new KeyNotFoundException("Finding state not found.");var baselines=await _repo.ListBaselinesAsync(projectId,5000,ct);var baseline=baselines.Where(x=>x.SubjectKey.Equals(state.SubjectKey,StringComparison.OrdinalIgnoreCase)&&x.Status==QaRegressionStatus.Regressed).OrderByDescending(x=>x.UpdatedAtUtc).FirstOrDefault();var candidates=new[]{baseline?.FirstBadCommit,state.LastCommitSha}.Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>x!).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();return new(fingerprint,baseline?.LastKnownGoodCommit,baseline?.FirstBadCommit,state.LastCommitSha,state.Team,state.Workstream,state.Occurrences,candidates,baseline is null?"No regression baseline exists yet; correlation is limited to the last observed commit.":"Candidates are bounded by the last-known-good and first-bad QA baseline. They are suspects, not proven causes.");}
    public async Task<QaFreshnessDto> GetFreshnessAsync(Guid projectId,int maxAgeDays,CancellationToken ct)
    {
        maxAgeDays=Math.Clamp(maxAgeDays,1,90);var p=await _repo.GetLatestProvenanceAsync(projectId,ct);if(p is null)return new(QaFreshnessStatus.Unknown.ToString(),int.MaxValue,maxAgeDays,null,null,"No QA provenance exists.","Unverified",0m);var age=Math.Max(0,(int)Math.Floor((_clock.UtcNow-p.CapturedAtUtc).TotalDays));var s=age>maxAgeDays?QaFreshnessStatus.Stale:age>Math.Max(1,maxAgeDays/2)?QaFreshnessStatus.Aging:QaFreshnessStatus.Fresh;decimal confidence=s switch{QaFreshnessStatus.Fresh=>90m,QaFreshnessStatus.Aging=>65m,QaFreshnessStatus.Stale=>30m,_=>0m};var health=(await _repo.ListSystemHealthAsync(projectId,1,ct)).FirstOrDefault();if(health?.Status==QaSystemHealthStatus.Degraded)confidence=Math.Min(confidence,55m);if(health?.Status==QaSystemHealthStatus.Unavailable)confidence=Math.Min(confidence,15m);var label=confidence>=80?"High":confidence>=55?"Medium":confidence>0?"Low":"Unverified";var reason=s==QaFreshnessStatus.Stale?"Evidence is older than the configured release freshness window.":"Evidence age is within the configured freshness window.";if(health?.Status is QaSystemHealthStatus.Degraded or QaSystemHealthStatus.Unavailable)reason+=$" QA self-health is {health.Status}, so confidence is reduced.";return new(s.ToString(),age,maxAgeDays,p.CommitSha,p.CapturedAtUtc,reason,label,confidence);
    }
    public static DiagnosticSchemaDto GetDiagnosticSchema()=>new("dip.finding.v2","2.0.0",["SARIF 2.x","JUnit-compatible XML","TRX","NUnit-compatible XML","generic JSON","unstructured text fallback"],"Normalized findings carry schema/source-format versions. New normalizers must preserve old readers or migrate explicitly; raw artifacts remain immutable.");
    public async Task<QaCostSummaryDto> GetCostSummaryAsync(Guid projectId,int take,CancellationToken ct){var x=await _repo.ListCostsAsync(projectId,take,ct);return new(x.Count,x.Sum(v=>v.WallDurationMs),x.Sum(v=>v.ToolDurationMs),x.Sum(v=>v.ArtifactBytes),x.Sum(v=>v.EstimatedCpuSeconds),x.Count(v=>v.BudgetVerdict=="OverBudget"));}
    public async Task<CrossProjectBenchmarkComparisonDto> CompareProjectsAsync(string definitionKey,string metricName,string aggregation,int take,CancellationToken ct)
    {var def=await _benchmarks.GetDefinitionByKeyAsync(definitionKey,ct)??throw new KeyNotFoundException($"Benchmark definition '{definitionKey}' not found.");var runs=await _benchmarks.ListSucceededRunsAsync(def.Id,Math.Clamp(take*20,20,5000),ct);var latest=runs.GroupBy(x=>x.ProjectId).Select(g=>g.OrderByDescending(x=>x.FinishedAtUtc).First()).Take(Math.Clamp(take,1,100)).ToArray();var rows=new List<(BenchmarkRun Run,decimal Value,string Unit)>();foreach(var run in latest){var metrics=await _benchmarks.ListMetricsAsync(run.Id,ct);var m=metrics.FirstOrDefault(x=>x.Name.Equals(metricName,StringComparison.OrdinalIgnoreCase)&&x.Aggregation.Equals(aggregation,StringComparison.OrdinalIgnoreCase));if(m is not null)rows.Add((run,m.Value,m.Unit));}if(rows.Count==0)return new(definitionKey,$"{metricName}.{aggregation}",[],"No comparable successful benchmark measurements exist.");var higherIsBetter=metricName.Equals("throughput",StringComparison.OrdinalIgnoreCase);var best=higherIsBetter?rows.Max(x=>x.Value):rows.Min(x=>x.Value);var result=new List<CrossProjectBenchmarkMetricDto>();foreach(var row in rows){var project=await _projects.GetByIdAsync(row.Run.ProjectId,ct);decimal diff;if(best==0)diff=row.Value==0?0m:100m;else diff=higherIsBetter?(best-row.Value)/Math.Abs(best)*100m:(row.Value-best)/Math.Abs(best)*100m;result.Add(new(row.Run.ProjectId,project?.Name??row.Run.ProjectId.ToString("N"),row.Run.Id,row.Run.CommitSha,row.Run.EnvironmentFingerprint,row.Value,row.Unit,aggregation,decimal.Round(diff,2)));}return new(definitionKey,$"{metricName}.{aggregation}",result.OrderBy(x=>x.DifferenceFromBestPercent).ToArray(),"Cross-project results are descriptive only. Compare identical benchmark definitions/configuration and equivalent hardware environments before drawing performance conclusions.");}

    private async Task ObserveBaselinesAsync(QaRun run,IReadOnlyList<QaFinding> findings,DateTimeOffset now,CancellationToken ct)
    {var commit=run.CommitSha!;var value=findings.Count(x=>x.Severity is Severity.Critical or Severity.Warning);var healthy=run.Status==QaRunStatus.Succeeded&&value==0;foreach(var metric in new[]{("qa.finding_count",(decimal)value),("qa.critical_count",(decimal)findings.Count(x=>x.Severity==Severity.Critical))}){var b=await _repo.FindBaselineAsync(run.ProjectId,run.SubjectKey,metric.Item1,ct);if(b is null){if(healthy){b=new QaRegressionBaseline(Guid.NewGuid(),run.ProjectId,run.SubjectKey,metric.Item1,commit,metric.Item2,now);await _repo.AddBaselineAsync(b,ct);}continue;}b.Observe(commit,metric.Item2,healthy,now);}}
    private static QaPolicyRules ReadRules(QaPolicy? p){if(p is null)return new();try{return JsonSerializer.Deserialize<QaPolicyRules>(p.RulesJson)??new();}catch(JsonException){return new();}}
    private static QaPolicyEvaluation EvaluatePolicy(QaRun run,IReadOnlyList<QaFinding> findings,IReadOnlyList<QaFindingState> states,IReadOnlyList<QaTestReliability> rel,IReadOnlyList<QaWaiver> waivers,QaPolicyRules rules,QaPolicy? p,int infrastructureFailures,long wallDurationMs,long cpuTimeMs,long artifactBytes,DateTimeOffset now)
    {var blockers=new List<string>();var warnings=new List<string>();var effective=findings.Where(f=>!waivers.Any(w=>w.IsActive(now)&&MatchesWaiver(w,f))).ToArray();var critical=effective.Count(x=>x.Severity==Severity.Critical);var warning=effective.Count(x=>x.Severity==Severity.Warning);if(critical>rules.MaxCriticalFindings)blockers.Add($"{critical} non-waived critical finding(s) exceed policy limit {rules.MaxCriticalFindings}.");if(warning>rules.MaxWarningFindings)warnings.Add($"{warning} warning finding(s) exceed policy limit {rules.MaxWarningFindings}.");var flaky=rel.Where(x=>x.Classification==TestReliabilityClassification.Flaky).ToArray();if(flaky.Any(x=>x.FailureRatePercent>rules.MaxFlakyRatePercent))warnings.Add("One or more flaky tests exceed the configured failure-rate limit.");if(run.Status==QaRunStatus.InfrastructureFailure&&rules.BlockOnUnavailableQa)blockers.Add("QA infrastructure is unavailable; product quality cannot be verified.");if(infrastructureFailures>rules.MaxInfrastructureFailures)blockers.Add($"{infrastructureFailures} recent QA infrastructure failure(s) exceed policy limit {rules.MaxInfrastructureFailures}.");if(rules.MaxRunDurationMs>0&&wallDurationMs>rules.MaxRunDurationMs)warnings.Add($"QA run duration {wallDurationMs} ms exceeds budget {rules.MaxRunDurationMs} ms.");var cpuSeconds=cpuTimeMs/1000m;if(rules.MaxCpuSeconds>0&&cpuSeconds>rules.MaxCpuSeconds)warnings.Add($"QA CPU time {cpuSeconds:0.###} s exceeds budget {rules.MaxCpuSeconds:0.###} s.");if(rules.MaxArtifactBytes>0&&artifactBytes>rules.MaxArtifactBytes)warnings.Add($"QA artifacts {artifactBytes} bytes exceed budget {rules.MaxArtifactBytes} bytes.");var verdict=blockers.Count>0?QaGateVerdict.NoGo:warnings.Count>0?QaGateVerdict.ReviewRequired:QaGateVerdict.Go;var summary=verdict switch{QaGateVerdict.Go=>"GO: QA policy requirements are satisfied.",QaGateVerdict.ReviewRequired=>"REVIEW REQUIRED: no hard QA blocker is open, but quality warnings need explicit review.",_=>"NO-GO: QA policy contains one or more release blockers."};return new QaPolicyEvaluation(Guid.NewGuid(),run.ProjectId,run.Id,p?.Id,p?.Version??"default-v1",verdict,JsonSerializer.Serialize(blockers),JsonSerializer.Serialize(warnings),summary,now);}
    private static QaEvidenceProvenance BuildProvenance(QaRun run,IReadOnlyList<QaFinding> findings,string policyVersion,DateTimeOffset now)
    {
        var environment=new{os=System.Runtime.InteropServices.RuntimeInformation.OSDescription,osArchitecture=System.Runtime.InteropServices.RuntimeInformation.OSArchitecture.ToString(),processArchitecture=System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(),framework=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,processorCount=Environment.ProcessorCount,machine=Environment.MachineName};
        var env=JsonSerializer.Serialize(environment);var envHash=Hash(env);var input=JsonSerializer.Serialize(new{run.ProjectId,run.SubjectKey,run.Language,run.WorkspaceRelativePath,run.CommitSha,run.CreatedAtUtc});var evidence=JsonSerializer.Serialize(findings.OrderBy(x=>x.Fingerprint).Select(x=>new{x.Fingerprint,x.Severity,x.Tool,x.DiagnosticSchemaVersion,x.SourceFormat,x.SourceFormatVersion}));
        var toolchain=BuildToolchainEvidence(run.SummaryJson,environment,policyVersion);
        return new QaEvidenceProvenance(Guid.NewGuid(),run.ProjectId,run.Id,run.CommitSha,envHash,toolchain,"2.0.0",policyVersion,Hash(input),Hash(evidence),now);
    }
    private static string BuildToolchainEvidence(string? summaryJson,object environment,string policyVersion)
    {
        var tools=new List<object>();var adapters=new List<object>();object? detected=null;
        if(!string.IsNullOrWhiteSpace(summaryJson))try{using var doc=JsonDocument.Parse(summaryJson);var root=doc.RootElement;if(root.TryGetProperty("tools",out var toolArray)&&toolArray.ValueKind==JsonValueKind.Array)foreach(var t in toolArray.EnumerateArray().Take(100)){string? Read(string name)=>t.TryGetProperty(name,out var v)&&v.ValueKind==JsonValueKind.String?v.GetString():null;long ReadLong(string name)=>t.TryGetProperty(name,out var n)&&n.TryGetInt64(out var value)?value:0;tools.Add(new{tool=Read("Tool")??Read("tool"),executable=Read("Executable")??Read("executable"),version=Read("Version")??Read("version"),sandbox=Read("SandboxJson")??Read("sandboxJson"),cpuTimeMs=ReadLong("CpuTimeMs")+ReadLong("cpuTimeMs")});}if(root.TryGetProperty("adapters",out var adapterArray)&&adapterArray.ValueKind==JsonValueKind.Array)foreach(var a in adapterArray.EnumerateArray().Take(50))adapters.Add(JsonSerializer.Deserialize<object>(a.GetRawText())!);if(root.TryGetProperty("detected",out var d))detected=JsonSerializer.Deserialize<object>(d.GetRawText());}catch(JsonException){}
        var full=JsonSerializer.Serialize(new{environment,normalizerVersion="2.0.0",governanceVersion=GovernanceVersion,policyVersion,detected,adapters,tools});if(full.Length<=15900)return full;return JsonSerializer.Serialize(new{environment,normalizerVersion="2.0.0",governanceVersion=GovernanceVersion,policyVersion,toolCount=tools.Count,note="Toolchain evidence was compacted to fit the durable provenance record; immutable QA artifacts contain complete stdout/stderr and run summary."});
    }
    private static bool IsProductFailure(QaFinding x)=>x.Severity==Severity.Critical||x.Category.Contains("test",StringComparison.OrdinalIgnoreCase)||x.Category.Contains("compile",StringComparison.OrdinalIgnoreCase)||x.Category.Contains("runtime",StringComparison.OrdinalIgnoreCase)||x.Category.Contains("crash",StringComparison.OrdinalIgnoreCase);
    private static bool IsClosed(FindingLifecycleStatus s)=>s is FindingLifecycleStatus.Verified or FindingLifecycleStatus.Closed or FindingLifecycleStatus.Duplicate or FindingLifecycleStatus.WontFix;
    private static bool MatchesWaiver(QaWaiver w,QaFinding f)=>(!string.IsNullOrWhiteSpace(w.Fingerprint)&&w.Fingerprint.Equals(f.Fingerprint,StringComparison.OrdinalIgnoreCase))||(!string.IsNullOrWhiteSpace(w.RuleId)&&string.Equals(w.RuleId,f.RuleId,StringComparison.OrdinalIgnoreCase))||(!string.IsNullOrWhiteSpace(w.PathPattern)&&Glob(w.PathPattern!,f.FilePath??""));
    private static bool TryOwner(IReadOnlyList<QaOwnershipRule> rules,string? path,out QaOwnershipRule? owner){owner=rules.FirstOrDefault(x=>Glob(x.PathPattern,path??""));return owner is not null;}
    internal static bool Glob(string pattern,string value){var p=(pattern??"").Replace('\\','/');var v=(value??"").Replace('\\','/');var rx="^"+Regex.Escape(p).Replace("\\*\\*",".*").Replace("\\*","[^/]*").Replace("\\?",".")+"$";return Regex.IsMatch(v,rx,RegexOptions.IgnoreCase|RegexOptions.CultureInvariant);}
    private static long ToolDuration(string? json){if(string.IsNullOrWhiteSpace(json))return 0;try{using var d=JsonDocument.Parse(json);if(!d.RootElement.TryGetProperty("tools",out var a)||a.ValueKind!=JsonValueKind.Array)return 0;return a.EnumerateArray().Sum(x=>x.TryGetProperty("DurationMs",out var n)&&n.TryGetInt64(out var v)?v:x.TryGetProperty("durationMs",out var n2)&&n2.TryGetInt64(out var v2)?v2:0);}catch{return 0;}}
    private static long CpuDuration(string? json){if(string.IsNullOrWhiteSpace(json))return 0;try{using var d=JsonDocument.Parse(json);if(!d.RootElement.TryGetProperty("tools",out var a)||a.ValueKind!=JsonValueKind.Array)return 0;return a.EnumerateArray().Sum(x=>x.TryGetProperty("CpuTimeMs",out var n)&&n.TryGetInt64(out var v)?v:x.TryGetProperty("cpuTimeMs",out var n2)&&n2.TryGetInt64(out var v2)?v2:0);}catch{return 0;}}
    private static long DirectorySize(string path){try{return Directory.Exists(path)?Directory.EnumerateFiles(path,"*",SearchOption.AllDirectories).Select(x=>new FileInfo(x).Length).Sum():0;}catch{return 0;}}
    private static QaSystemHealthStatus AssessSelfHealth(QaRun run)
    {if(run.Status==QaRunStatus.InfrastructureFailure)return QaSystemHealthStatus.Unavailable;if(string.IsNullOrWhiteSpace(run.SummaryJson))return QaSystemHealthStatus.Degraded;try{using var d=JsonDocument.Parse(run.SummaryJson);var r=d.RootElement;var adapterFailures=r.TryGetProperty("adapterFailures",out var af)&&af.ValueKind==JsonValueKind.Array?af.GetArrayLength():0;var unavailable=r.TryGetProperty("unavailableLanguages",out var ul)&&ul.ValueKind==JsonValueKind.Array?ul.GetArrayLength():0;var unsupported=r.TryGetProperty("unsupportedDetectedLanguages",out var ud)&&ud.ValueKind==JsonValueKind.Array?ud.GetArrayLength():0;return adapterFailures+unavailable+unsupported>0?QaSystemHealthStatus.Degraded:QaSystemHealthStatus.Healthy;}catch(JsonException){return QaSystemHealthStatus.Degraded;}}
    private static IReadOnlyList<QaSystemHealthSnapshot> BuildToolHealthSnapshots(QaRun run,DateTimeOffset now)
    {var result=new List<QaSystemHealthSnapshot>();if(string.IsNullOrWhiteSpace(run.SummaryJson))return result;try{using var d=JsonDocument.Parse(run.SummaryJson);if(!d.RootElement.TryGetProperty("tools",out var tools)||tools.ValueKind!=JsonValueKind.Array)return result;foreach(var t in tools.EnumerateArray().Take(100)){var name=ReadString(t,"Tool")??ReadString(t,"tool")??"unknown";var available=ReadBool(t,"WasAvailable")??ReadBool(t,"wasAvailable")??false;var sandbox=ReadString(t,"SandboxJson")??ReadString(t,"sandboxJson");var sandboxEnabled=ReadSandboxEnabled(sandbox);var status=!available?QaSystemHealthStatus.Degraded:sandboxEnabled==false?QaSystemHealthStatus.Degraded:QaSystemHealthStatus.Healthy;var detail=!available?"QA dependency/tool was unavailable; this is infrastructure evidence, not a product defect.":sandboxEnabled==false?"QA tool executed without the configured process sandbox boundary.":"QA tool was available and the configured execution boundary was applied when supported.";result.Add(new QaSystemHealthSnapshot(Guid.NewGuid(),run.ProjectId,run.Id,Clip("tool:"+name,120),status,detail,now));}}catch(JsonException){}return result;}
    private static string? ReadString(JsonElement e,string name)=>e.TryGetProperty(name,out var v)&&v.ValueKind==JsonValueKind.String?v.GetString():null;private static bool? ReadBool(JsonElement e,string name)=>e.TryGetProperty(name,out var v)&&(v.ValueKind is JsonValueKind.True or JsonValueKind.False)?v.GetBoolean():null;private static bool? ReadSandboxEnabled(string? json){if(string.IsNullOrWhiteSpace(json))return null;try{using var d=JsonDocument.Parse(json);return ReadBool(d.RootElement,"Enabled")??ReadBool(d.RootElement,"enabled");}catch{return null;}}private static string Clip(string value,int max)=>value.Length<=max?value:value[..max];
    private static string HealthDetail(QaRun r,QaSystemHealthStatus health)=>health switch{QaSystemHealthStatus.Unavailable=>"QA adapters/tools were unavailable or failed before product quality could be determined.",QaSystemHealthStatus.Degraded=>"QA infrastructure completed with an unavailable adapter/tool, unsupported detected technology, or incomplete execution boundary. Product findings are tracked separately.",_=>"QA orchestration infrastructure completed successfully. Product failures, warnings, and regressions are tracked separately from QA self-health."};
    private static string Hash(string text)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
}
